```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - I didn't say it was impossible, just extremely difficult
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [
      { id: '1', name: 'Isolinear Chip', price: 49.99 },
      { id: '2', name: 'Plasma Conduit', price: 129.99 }
    ],
    total: 179.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '1701 Deep Space Nine',
  city: 'Bajor Sector',
  state: 'CA',
  zip: '94102'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Miles O Brien'
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-DS9-001' });
  });

  // Happy path - complete checkout flow
  describe('Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByRole('status', { name: /order confirmation/i })).toBeInTheDocument();
      expect(screen.getByText('ORD-DS9-001')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-DS9-001');
    });
  });

  // Form validation
  describe('Shipping Validation', () => {
    it('displays error when street address is empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // Error states and recovery
  describe('Payment Error Handling', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review (fill forms)
      await fillShippingForm(user);
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);

      // Retry succeeds
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-RETRY-001' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText('ORD-RETRY-001')).toBeInTheDocument();
    });
  });

  // Loading states
  describe('Loading States', () => {
    it('disables buttons and shows processing state during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await fillPaymentForm(user);

      const placeOrderBtn = screen.getByRole('button', { name: /place order/i });
      await user.click(placeOrderBtn);

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  // Accessibility
  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('progress navigation indicates current step', () => {
      render(<Checkout />);
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      expect(within(nav).getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });

  // Edge cases
  describe('Edge Cases', () => {
    it('shows empty cart message when cart has no items', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });

      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});

// Helper functions
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street/i), validShipping.street);
  await user.type(screen.getByLabelText(/city/i), validShipping.city);
  await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
  await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function fillPaymentForm(user) {
  await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
  await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
  await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
  await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
